OUT=pathlib.Path('/app/output')
Q=np.array([0.,1.,0.,0.])
class Painter:
 def __init__(self):
  self.r=Robot();self.o=self.r.get_obs(cameras=[]);self.pos=np.array(self.o.meta['proprio']['now'][7:10]);self.buf=[]
 def move(self,p,seconds=1):
  p=np.array(p);n=max(1,int(np.ceil(seconds*20)),int(np.ceil(np.linalg.norm(p-self.pos)/.006)))
  self.buf.extend([np.r_[v,Q].tolist() for v in np.linspace(self.pos,p,n+1)[1:]]);self.pos=p.copy()
 def flush(self,label='motion',cams=['practice_cam']):
  while self.buf:
   a=self.buf[:180];self.buf=self.buf[180:];st=self.r.status();idx=st['calls']
   np.save(OUT/f'actions_{idx:04d}.npy',a)
   try:res=self.r.submit('ee_pose',a,dt=.05,cameras=cams,video='none',note=label)
   except Exception:
    stat=self.r.wait_ready();print('Recovered status',stat,flush=True);raise
   res.save(str(OUT/f'run_{idx:04d}'))
